"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1416],{70335:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Parses a chat message into a command object.\\n\\nReturns `nil` when the text does not start with the `/` prefix. A parsed object\\nwhose first word is not a registered command is still returned, but with `valid`\\nunset, so [ChatCommand:process] does nothing with it.\\n\\nErrors if `data.player` is missing or `data.text` is not a string.","params":[{"name":"data","desc":"Speaker, message, and their permission tier","lua_type":"{ player: Player, text: string, userLevel: number? }"}],"returns":[{"desc":"The parsed command, or nil if the text was not a command","lua_type":"ChatCommand?"}],"function_type":"static","source":{"line":97,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"use","desc":"Loads a table of commands, or requires a ModuleScript that returns one, and merges\\nit into the registry.\\n\\nEvery entry is checked for a handler at index 1 and errors if one is missing, so a\\nmalformed command table fails at load rather than at first use. Names already in\\nthe registry are overwritten.","params":[{"name":"source","desc":"Commands to register","lua_type":"{ [string]: Command } | ModuleScript"}],"returns":[],"function_type":"static","source":{"line":141,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"insert","desc":"Registers a single command, overwriting any existing one of that name.","params":[{"name":"name","desc":"Word typed after the `/` prefix","lua_type":"string"},{"name":"command","desc":"Handler and flags","lua_type":"Command"}],"returns":[],"function_type":"static","source":{"line":170,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"getPlayers","desc":"Resolves a target selector to a list of players.\\n\\n`me` (or no text) is the caller, `all` is everyone, `others` is everyone but the\\ncaller, and anything else is matched as a Lua pattern against player names \u2014\\nreturning at most one player, the first match.\\n\\n:::caution Name matching is a pattern match\\nThe selector is fed to `string.match`, not compared literally, so a name\\ncontaining pattern characters can behave unexpectedly.\\n:::","params":[{"name":"player","desc":"Caller, used to resolve `me` and `others`","lua_type":"Player"},{"name":"text","desc":"Selector text","lua_type":"string?"},{"name":"ignoreIfDead","desc":"Drop players who are not alive","lua_type":"boolean?"}],"returns":[{"desc":"","lua_type":"{ Player }"}],"function_type":"static","source":{"line":197,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"test","desc":"Whether a message begins with the command prefix. Does not check that the command\\nexists \u2014 see [ChatCommand.exists] for that.","params":[{"name":"text","desc":"Raw chat message","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":242,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"exists","desc":"Whether a command of this name is registered. Case sensitive.","params":[{"name":"name","desc":"Command name","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":255,"path":"src/Shared/Class/ChatCommand.luau"}},{"name":"process","desc":"Runs the parsed command, if it is valid and the speaker is permitted.\\n\\nDoes nothing when the message was not a recognised command, or when the speaker\'s\\n`userLevel` is below the command\'s `minimumLevel` \u2014 an unauthorized attempt is\\nignored silently rather than reported.\\n\\nTargets are resolved first (unless the command sets `noTargets`), then the handler\\nis called as `handler(targets, ...remainingWords)`. The handler runs on the calling\\nthread, so a yielding command blocks the caller.","params":[],"returns":[],"function_type":"method","source":{"line":273,"path":"src/Shared/Class/ChatCommand.luau"}}],"properties":[],"types":[{"name":"Command","desc":"A registered command: its handler at index 1, plus optional flags controlling how\\ntargets are resolved and who may run it.\\n\\n`noTargets` skips selector parsing entirely, so the caller alone is the target and\\nthe first word stays an ordinary argument. `adminsExempt` is for punitive commands\\n\u2014 it drops superusers from the target list so they cannot be hit by `all`.","fields":[{"name":"[1]","lua_type":"(targets: { Player }, ...string) -> ()","desc":"The handler; required"},{"name":"ignoreIfDead","lua_type":"boolean?","desc":"Only passes alive players through the targets table"},{"name":"noTargets","lua_type":"boolean?","desc":"Doesn\'t insert targets during command processing"},{"name":"minimumLevel","lua_type":"number?","desc":"Minimum user level required to use the command"},{"name":"adminsExempt","lua_type":"boolean?","desc":"Admins included in the call are not inserted into the targets table"}],"source":{"line":52,"path":"src/Shared/Class/ChatCommand.luau"}}],"name":"ChatCommand","desc":"Parses and dispatches slash commands typed into chat.\\n\\nCommands are registered up front with [ChatCommand.use] or [ChatCommand.insert],\\nthen each chat message is turned into a ChatCommand with [ChatCommand.new] and run\\nwith [ChatCommand:process]. Messages that do not start with `/`, or whose first\\nword is not a registered command, are ignored.\\n\\nA command\'s first argument is normally a *target selector* \u2014 `me`, `all`,\\n`others`, or a partial player name \u2014 which [ChatCommand.getPlayers] resolves to a\\nlist of players. The selector is consumed, and everything after it is passed to the\\ncommand as plain string arguments.\\n\\n```lua\\nChatCommand.use({\\n\\tkill = { function(targets: { Player })\\n\\t\\tfor _, target in targets do\\n\\t\\t\\ttarget.Character.Humanoid.Health = 0\\n\\t\\tend\\n\\tend, minimumLevel = Util.userLevel.moderator },\\n})\\n\\nlocal command = ChatCommand.new({ player = player, text = message, userLevel = level })\\n\\nif command then\\n\\tcommand:process()\\nend\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":35,"path":"src/Shared/Class/ChatCommand.luau"}}')}}]);